/**
 * OB Admin only. `code` is unique case-insensitively, and the service
refuses a duplicate with a field-keyed `409` rather than letting the
index refuse it with a message naming a MySQL constraint — the call
`createClient` already made one master over.

**A product with no journey template cannot be bought.** Creating one
here does not make it selectable on OB-04; that needs an active
template (`ob_journey_templates.product_id`), because a purchase with
no template to instantiate would board a client into nothing. The
wizard's picker reads `hasActiveTemplate`.

 * @summary Add a product to the catalogue (OB-07) — OB Admin
 */
export const createObProductHeader = zod.object({
  "Idempotency-Key": zod.string().uuid().optional().describe('Replaying a key within 24 hours returns the original response instead of\ncreating a second row. Send one on every create — a retried request after\na network timeout is the normal case, not the exception.\n')
})

export const createObProductBodyCodeMax = 32;


export const createObProductBodyCodeRegExp = new RegExp('^[A-Z0-9_-]+$');
export const createObProductBodyNameMax = 160;

export const createObProductBodyIsActiveDefault = true;

export const createObProductBody = zod.object({
  "code": zod.string().max(createObProductBodyCodeMax).regex(createObProductBodyCodeRegExp),
  "name": zod.string().max(createObProductBodyNameMax),
  "isActive": zod.boolean().default(createObProductBodyIsActiveDefault)
})

